package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

const (
	registryFile     = "/app/models/registry.idx"
	registryJSONFile = "/app/models/registry.json"
)

type RegistryEntry struct {
	Name    string   `json:"name"`
	Path    string   `json:"path"`
	Type    string   `json:"type"`
	Version int      `json:"version"`
	Created string   `json:"created"`
	Tags    []string `json:"tags"`
}

func loadRegistry() ([]RegistryEntry, error) {
	data, err := os.ReadFile(registryJSONFile)
	if err == nil {
		if len(strings.TrimSpace(string(data))) == 0 {
			return nil, nil
		}
		var entries []RegistryEntry
		if err := json.Unmarshal(data, &entries); err != nil {
			return nil, fmt.Errorf("parse registry.json: %w", err)
		}
		for i := range entries {
			entries[i].Tags = ensureTags(entries[i].Tags)
		}
		return entries, nil
	}
	if !os.IsNotExist(err) {
		return nil, err
	}

	if _, err := os.Stat(registryFile); err == nil {
		entries, err := loadOldRegistry()
		if err != nil {
			return nil, err
		}
		if err := saveRegistry(entries); err != nil {
			return nil, err
		}
		return entries, nil
	}

	return nil, nil
}

func loadOldRegistry() ([]RegistryEntry, error) {
	f, err := os.Open(registryFile)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	defer f.Close()

	var entries []RegistryEntry
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.Split(line, "|")
		if len(parts) != 5 {
			continue
		}
		ver := 1
		fmt.Sscanf(parts[3], "%d", &ver)
		entries = append(entries, RegistryEntry{
			Name:    parts[0],
			Path:    parts[1],
			Type:    parts[2],
			Version: ver,
			Created: parts[4],
			Tags:    []string{},
		})
	}
	return entries, scanner.Err()
}

func saveRegistry(entries []RegistryEntry) error {
	dir := filepath.Dir(registryJSONFile)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}

	out := make([]RegistryEntry, len(entries))
	for i, e := range entries {
		e.Tags = ensureTags(e.Tags)
		out[i] = e
	}

	data, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(registryJSONFile, data, 0644)
}

func ensureTags(tags []string) []string {
	if tags == nil {
		return []string{}
	}
	return tags
}

func findEntry(entries []RegistryEntry, name string) *RegistryEntry {
	for i := range entries {
		if entries[i].Name == name {
			return &entries[i]
		}
	}
	return nil
}

func cmdList(args []string) {
	entries, err := loadRegistry()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	if len(entries) == 0 {
		fmt.Println("No models registered.")
		return
	}

	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Name < entries[j].Name
	})

	for _, e := range entries {
		tags := append([]string(nil), e.Tags...)
		sort.Strings(tags)
		if len(tags) > 0 {
			fmt.Printf("%s (%s)\n", e.Name, strings.Join(tags, ", "))
		} else {
			fmt.Println(e.Name)
		}
	}
}

func cmdInfo(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "usage: mlpipe info <model>\n")
		os.Exit(1)
	}
	name := args[0]
	entries, err := loadRegistry()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	entry := findEntry(entries, name)
	if entry == nil {
		fmt.Fprintf(os.Stderr, "error: model '%s' not found\n", name)
		os.Exit(1)
	}
	if !modelDirExists(entry.Path) {
		fmt.Fprintf(os.Stderr, "error: model directory not found\n")
		os.Exit(1)
	}

	meta, err := loadModelMeta(entry.Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading metadata: %v\n", err)
		os.Exit(1)
