	entries, err := loadRegistry()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	if findEntry(entries, name) != nil {
		fmt.Fprintf(os.Stderr, "error: model '%s' already registered\n", name)
		os.Exit(1)
	}

	modelType := meta["type"]
	if modelType == "" {
		modelType = "unknown"
	}

	entries = append(entries, RegistryEntry{
		Name:    name,
		Path:    absPath,
		Type:    modelType,
		Version: 1,
		Created: time.Now().Format("2006-01-02"),
		Tags:    []string{},
	})

	if err := saveRegistry(entries); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("Model '%s' registered successfully.\n", name)
}

func cmdRemove(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "usage: mlpipe remove <name>\n")
		os.Exit(1)
	}
	name := args[0]

	entries, err := loadRegistry()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	found := false
	var newEntries []RegistryEntry
	for _, e := range entries {
		if e.Name == name {
			found = true
		} else {
			newEntries = append(newEntries, e)
		}
	}

	if !found {
		fmt.Fprintf(os.Stderr, "error: model '%s' not found\n", name)
		os.Exit(1)
	}

	if err := saveRegistry(newEntries); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("Model '%s' removed.\n", name)
}

func isValidTag(tag string) bool {
	if tag == "" {
		return false
	}
	for _, c := range tag {
		isLower := c >= 'a' && c <= 'z'
		isDigit := c >= '0' && c <= '9'
		isHyphen := c == '-'
		if !(isLower || isDigit || isHyphen) {
			return false
		}
	}
	return true
}

func hasTag(entry *RegistryEntry, tag string) bool {
	for _, t := range entry.Tags {
		if t == tag {
			return true
		}
	}
	return false
}

func cmdTag(args []string) {
	if len(args) < 2 {
		fmt.Fprintf(os.Stderr, "usage: mlpipe tag <model> <tag>\n")
		os.Exit(1)
	}
	name := args[0]
	tag := args[1]

	if !isValidTag(tag) {
		fmt.Fprintf(os.Stderr, "error: invalid tag '%s'\n", tag)
		os.Exit(1)
	}

	entries, err := loadRegistry()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	entry := findEntry(entries, name)
	if entry == nil {
		fmt.Fprintln(os.Stderr, "not found")
		os.Exit(1)
	}

	if hasTag(entry, tag) {
		return
	}

	entry.Tags = append(entry.Tags, tag)
	sort.Strings(entry.Tags)

	if err := saveRegistry(entries); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("tagged '%s' with '%s'\n", name, tag)
}

func cmdUntag(args []string) {
	if len(args) < 2 {
		fmt.Fprintf(os.Stderr, "usage: mlpipe untag <model> <tag>\n")
		os.Exit(1)
	}
	name := args[0]
	tag := args[1]

	entries, err := loadRegistry()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	entry := findEntry(entries, name)
	if entry == nil {
		fmt.Fprintln(os.Stderr, "not found")
		os.Exit(1)
	}

	idx := -1
	for i, t := range entry.Tags {
		if t == tag {
			idx = i
			break
		}
	}
	if idx < 0 {
		fmt.Fprintln(os.Stderr, "tag not found")
		os.Exit(1)
	}

	entry.Tags = append(entry.Tags[:idx], entry.Tags[idx+1:]...)
	if entry.Tags == nil {
		entry.Tags = []string{}
	}

	if err := saveRegistry(entries); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("removed tag '%s' from '%s'\n", tag, name)
}

func cmdSearch(args []string) {
	flags := parseFlags(args)

	var tagFilter, nameFilter string
	hasTagFilter, hasNameFilter := false, false

	if v, ok := flags["tag"]; ok {
		if v == "true" {
			fmt.Fprintf(os.Stderr, "usage: mlpipe search [--tag <tag>] [--name <pattern>]\n")
			os.Exit(1)
		}
		tagFilter = v
		hasTagFilter = true
	}
	if v, ok := flags["name"]; ok {
		if v == "true" {
			fmt.Fprintf(os.Stderr, "usage: mlpipe search [--tag <tag>] [--name <pattern>]\n")
			os.Exit(1)
		}
		nameFilter = v
		hasNameFilter = true
	}

	entries, err := loadRegistry()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	var names []string
	for _, e := range entries {
		if hasNameFilter && !strings.Contains(strings.ToLower(e.Name), strings.ToLower(nameFilter)) {
			continue
		}
		if hasTagFilter {
			found := false
			for _, t := range e.Tags {
				if t == tagFilter {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}
		names = append(names, e.Name)
	}

	sort.Strings(names)
	for _, name := range names {
		fmt.Println(name)
	}
}
